import json, csv, re
from pathlib import Path
P=Path(__file__).parent
talks=[]; items=[]; problems=[]; corrections=[]; areas={}
def talk(record,date,speaker,pages,title,summary):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(record,pages,kind,title,notes,statement,cl,fate,refs=(),reconstruction='',correct='correct with missing hypotheses',match='partial',verification='read the result',status='',problem='',worth='',development='annotated',confidence='high',speaker=None,area=''):
    ident=f'1980-{record}.{sum(i["record"]==record for i in items)+1}'
    obj=dict(id=ident,record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status=status or 'As of November 2026, the qualified statement above is established; no new open problem is inferred from the omissions in the notebook.',literal_correctness=correct,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:obj['speaker']=speaker
    items.append(obj);areas[ident]=area or ('integrable systems' if record<=519 else 'representation theory' if record in (520,528) else 'algebraic geometry' if record==521 else 'algebraic K-theory' if record==522 else 'partial differential equations and kinetic theory' if record<=527 else 'other')
    return ident
def correction(page,place,old,new,evidence,applies='both',typ='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=old,should_read=new,evidence=evidence,applies_to=applies,type=typ))
def save():
    for name,data in [('talks',talks),('items',items),('problems',problems),('areas',areas)]:
        (P/f'spring_{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (P/'spring_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

talk(511,'1981-02-23','I. M. Gelfand','P000960','Dixmier operators and Grinevich’s construction',r'The opening of the manuscript dated 23 February 1981 reports Dixmier’s commuting operators of orders four and six, then Grinevich’s extension using Tyurin parameters. The catalogue places this record in 1991; the autograph date and the surrounding 1981 sequence establish a catalogue decade error. This recovered entry precedes Cherednik’s talk in manuscript order.')
talk(510,'1981-02-23','I. V. Cherednik','P000960-P000961','Inverse scattering, elliptic zero curvature, and Yang–Baxter structures',r'Cherednik presents three stages of soliton theory, from scalar inverse scattering through matrix zero curvature to the Yang--Baxter equation, with elliptic examples and Landau--Lifshitz dynamics. Only the upper portion of P000961 belongs here; Khovanskii begins below it. The manuscript dates this material 23 February 1981, correcting the catalogue’s 1991 date.')
talk(514,'1981-03-02','I. V. Cherednik','P000964-P000965','A diagram relating Yang–Baxter structures',r'A short diagrammatic reprise links factorized scattering, two-dimensional statistical mechanics, quantum one-dimensional systems, and integrable equations. Belavin adds unitarity. Gelfand’s preceding Gaussian-tail exercise is retained here as an explicitly attributed intervention; his adjacent Kazarnovskii question is indexed with record 513. The detailed three-stage account is in recovered record 510, not this March entry.')
talk(515,'1981-03-02','A. A. Belavin','P000965-P000966','Inversion, crossing, and Baxter invariant curves',r'Belavin studies matrix inversion and partial transposition, then the invariant quantities of the symmetric eight-vertex matrix. Elliptic curves appear after projectivizing and imposing generic smoothness. The notebook’s symmetry sign and the distinction between generic and exceptional orbits require qualification.')
talk(516,'1981-03-02','I. V. Cherednik','P000966-P000968','Factorized scattering and commuting transfer operators',r'The continuation derives the Yang--Baxter relation from three-particle reordering, rewrites it in tensor notation, gives an elliptic Pauli-matrix solution, and states the commuting-transfer-operator mechanism. The index in the component relation and the tensor leg traced in the last theorem are faithfully recorded mathematical errors, not transcription mistakes.')
talk(517,'1981-03-23','I. M. Gelfand','P000969','Moser’s isospectral formulation of ellipsoid geodesics',r'Gelfand discusses Moser’s contribution to the Chern Symposium, giving the constrained geodesic equation and a projected matrix with constant spectrum. Jacobi’s earlier integration is mentioned; the displayed matrix construction is the modern Moser formulation.')
talk(518,'1981-03-23','P. G. Grinevich','P000969-P000970','Rational commuting differential operators of rank two',r'Grinevich explains the elliptic rank-two Krichever--Novikov construction in Tyurin parameters and its rational specializations. The Dixmier case is a choice of rational parameter, not a consequence of setting the centre parameter to zero alone.')
talk(519,'1981-03-23','A. A. Kirillov; I. M. Gelfand','P000970','A Dixmier formula and algebraic curves in the Weyl division ring',r'Kirillov gives a formal pseudodifferential description, followed by the question of rational commuting operators with a prescribed genus-two spectral curve. Gelfand proposes an embedding of the function field of any algebraic curve in the rank-one Weyl division ring. The sixth-order formula needs emendation, and the universal curve assertion remains distinct from results for generic genus-two curves or some curves of every genus.')
talk(520,'1981-03-23','J.-L. Brylinski','P000970','Verma modules and geometric realization',r'The uncertain handwritten surname is resolved by the explicit Kashiwara collaboration and the subject. The short record defines Verma modules and gestures toward realizations on the flag variety, with an SL(2) example. It does not state a new proof of the Kazhdan--Lusztig formula.')
talk(521,'1981-03-23','E. Viehweg','P000971','Classification of threefolds after Esnault’s Bourbaki report',r'The talk explicitly follows Hélène Esnault’s February 1981 Bourbaki exposition. Kodaira dimension, irregularity, abelian varieties, and Albanese fibrations of threefolds are summarized. A question mark in the irregularity-zero case is preserved as an incomplete classification entry, not promoted to a newly formulated conjecture.')
talk(522,'1981-03-23','C. Kassel; C. Soulé','P000971-P000972','K-theory of spaces and arithmetic K-groups',r'The manuscript has separate headings for Christian Kassel and Christophe Soulé, although the catalogue supplies only the Kassel record. Kassel reports Waldhausen’s programme and homotopy-ring constructions. Soulé’s contribution concerns orders of K-groups of the integers and zeta values; its bibliographic shorthand is not an exact identification of an Inventiones paper dated February 1980.')
talk(523,'1981-03-30','I. M. Gelfand','P000973','The collisionless Vlasov description',r'A brief introduction explains a self-consistent field generated by many charged particles whose binary collisions are neglected. The record states a modelling principle, not a quantified mean-field limit theorem.')
talk(524,'1981-03-30','V. I. Arnold','P000973-P000974','Weinstein’s Hamiltonian formulations of continua',r'Arnold begins with the geodesic interpretation of incompressible Euler flow, then describes reduction to coadjoint orbits and the extension to Vlasov and gauge-coupled kinetic equations. The density variable required for compressible fluid mechanics is mentioned but no full bracket is written.')
talk(525,'1981-03-30','A. V. Bobylev','P000974-P000975','Maxwell molecules and Fourier methods for Boltzmann’s equation',r'Bobylev presents the spatially homogeneous collision equation and singles out inverse-fourth-power potentials. Fourier methods, Gaussian convolution, linearization, and the isotropic nonlinear hierarchy appear, together with remarks on exact solutions and hydrodynamic limits. Angular cutoff, function-space, and normalization assumptions must be supplied when interpreting the compact-operator claim.')
talk(526,'1981-03-30','B. V. Lidskii','P000975-P000976','Spectra of sums of Hermitian matrices',r'Lidskii announces the recursive Horn inequalities and a connection with tensor-product multiplicities. His two-page announcement appeared in 1982, but the later literature distinguishes it from a published proof. Klyachko’s work and the Knutson--Tao saturation theorem provide the established resolution.')
talk(527,'1981-04-06','S. G. Krein','P000977-P000978','Compressible fluids, shocks, and dispersive step evolution',r'Krein reports the diffeomorphism-group approach to compressible flow and the incompressible limit. Scalar characteristics and shock formation prompt interventions by Gelfand and Zakharov. Gelfand’s final question concerns step-like data for a polynomial regularization of Burgers’ equation; the polynomial is not specified, so distinct dispersive and dissipative cases must be separated.')
talk(528,'1981-04-06','G. I. Olshanskii','P000978-P000980','Invariant cones, Lie semigroups, and highest-weight representations',r'Olshanskii develops semigroups of contractions, invariant cones in Hermitian Lie algebras, and holomorphic extension of unitary highest-weight representations. The primary paper was received in December 1980 and published in 1981. Properness of cones, a choice of sign, and the analytic representation category are essential qualifications absent from the shorthand notes.')

item(511,'P000960','theorem','Dixmier’s commuting operators of orders four and six',r'Two monic polynomial-coefficient operators of orders four and six commute but are not both functions of a single operator of order two; the note writes a square-root relation.',r'In the first Weyl algebra over \(\mathbb C\), there exist commuting ordinary differential operators of orders \(4,6\), rank \(2\), whose joint spectral curve is an elliptic cubic. The rank-two qualification concerns the generic common eigenspace, not merely the greatest common divisor of the two displayed orders.','E',r'This is the 1968 Dixmier example, revisited explicitly on P000970; see \citet{dixmier1968weyl}. The corrected operators and their algebraic identity are checked in the development section.',['dixmier1968weyl'],match='exact',verification='publisher metadata checked',development='annotated')
item(511,'P000960','claim','Grinevich’s rational rank-two generalization',r'Gelfand says Grinevich obtained many examples using Tyurin parameters.',r'The identifiable content is a family of commuting rational-coefficient rank-two operators associated with an elliptic spectral curve, developed in the detailed talk on P000969--P000970. No numerical count or completeness assertion is recorded here.','A',r'Compare the rational-coefficient construction in \citet{grinevich1982rational}; the fuller occurrence is record 518.',['grinevich1982rational'],match='partial',verification='publisher metadata checked')
item(510,'P000960','method','KdV inverse scattering and the recorded Lax pair',r'Stage I displays \(u_t=6uu_x+u_{xxx}\), \(L=D^2-u\), \(A=D^3-uD-Du\), and \([L,A]=L_t\).',r'For a smooth scalar function \(u\), a consistent normalization is \(L=D^2+u\), \(A=-4D^3-3(uD+Du)\), and \(L_t=[L,A]\), which yields \(u_t=6uu_x+u_{xxx}\). For sufficiently decaying real potentials the associated one-dimensional scattering data supply the inverse-scattering variables.','E',r'The isospectral method precedes the talk; see \citet[pp.~467--490]{lax1968integrals}. Direct use of \(Df=fD+f^{\prime}\) shows that the notebook’s three displayed formulas do not form this Lax pair.',['lax1968integrals'],correct='false as written',reconstruction=r'The signs and factors in \(L,A\) are an explicit emendation. The decay conditions belong to the scattering interpretation, not to the purely differential-operator identity.',match='partial')
item(510,'P000960','method','Matrix zero-curvature equations',r'Stage II uses \([D_x-U,D_t-V]=0\), with \(U,V\) rational in the spectral parameter; an example has degrees two and one.',r'For matrix-valued \(U(x,t,\lambda),V(x,t,\lambda)\), compatibility of \(\psi_x=U\psi\), \(\psi_t=V\psi\) is \(U_t-V_x+[U,V]=0\) at each regular value of \(\lambda\). A spectral-parameter representation alone does not establish a Hamiltonian structure or completeness of inverse scattering.','E',r'This is the established zero-curvature formulation; the relativistic elliptic models discussed next belong to the programme in \citet{cherednik1981quasiclassical}, submitted 8 August 1980 and published in 1981.',['cherednik1981quasiclassical'],match='partial',verification='publisher metadata checked')
item(510,'P000960-P000961','remark','The third-stage unification slogan',r'The Yang--Baxter equation is presented as the third stage, encompassing all or almost all integrable systems and connecting scattering with statistical mechanics.',r'The diagram records a programme of constructions and limiting procedures between specified models. It is not a theorem that every system called integrable arises from a Yang--Baxter equation.','F',r'\citet[Introduction]{belavin1980discrete} gives concrete scattering/discrete-symmetry constructions; it does not prove the unqualified universality slogan.',['belavin1980discrete'],correct='not determinable',match='thematic only',confidence='high',status='As of November 2026, this broad slogan has no single precise mathematical proposition whose truth or resolution could be assigned.')
item(510,'P000961','construction','Elliptic linear systems for anisotropic vector equations',r'The auxiliary vector \(E\) satisfies \(E_x=(J(\lambda-\alpha)V)\times E\), \(E_t=(J(\lambda)U)\times E\). The ensuing nonlinear system has \(U_x=(JV)\times U\) and a second line written with \(U_t\).',r'An elliptic spectral parameter can enter an \(\mathfrak{so}_3\)-valued flat connection by identifying vectors with cross-product matrices. Compatibility requires the coefficient of each independent elliptic function in its curvature to vanish. The exact two-field system cannot be recovered from an unspecified elliptic matrix \(J(\lambda)\) and the repeated \(U\) in the second line alone.','A',r'The subject matches Cherednik’s relativistic quasiclassical models \citep[abstract and pp.~422--425]{cherednik1981quasiclassical}; this is a partial, not equation-by-equation, identification.',['cherednik1981quasiclassical'],correct='not determinable',verification='publisher metadata checked',confidence='medium',reconstruction=r'The missing equality sign in the \(E_t\) line is syntactic; replacing the second \(U_t\) by \(V_t\) would be a mathematical conjecture about the intended system and is not silently adopted.',status='As of November 2026, the construction is identifiable at the level of elliptic zero-curvature models, but the exact notebook normalization is unresolved.')
item(510,'P000961','claim','Landau–Lifshitz dynamics and scattering brackets',r'The notes write \(U_t=U\times U_{xx}+(JU)\times U\) and say that Yang--Baxter theory supplies Hamiltonian and scattering brackets.',r'For a smooth spin field of fixed length and a constant diagonal anisotropy matrix \(J\), this is an anisotropic Landau--Lifshitz equation, with sign determined by the spin Poisson bracket convention. A statement about brackets of scattering data additionally requires a chosen Lax representation and boundary conditions.','E',r'Classical and quantum inverse-scattering constructions already precede this lecture; compare \citet{sklyaninfaddeev1978quantum}. The notebook does not specify the scattering-data bracket to be identified.',['sklyaninfaddeev1978quantum'],match='thematic only',verification='publisher metadata checked',confidence='medium')
correction('P000960','date heading for recovered records 510 and 511','MCCME catalogue: 23-Feb-91','1981-02-23','Autograph 23/II/81 and uninterrupted surrounding 1981 entries; catalogue decade error.','both','provenance')
correction('P000960','Stage I Lax pair',r'L=D^2-u; A=D^3-uD-Du; [L,A]=L_t',r'One consistent choice for the printed PDE: L=D^2+u, A=-4D^3-3(uD+Du), L_t=[L,A]','Autograph confirms formulas; Weyl multiplication gives the corrected identity.')
correction('P000961','elliptic auxiliary system, second line',r'E_t (J(lambda)U) cross E',r'E_t=(J(lambda)U) cross E','Missing equality sign is visible in the autograph; mathematical normalization still requires separate checking.','both','transcription')
correction('P000961','nonlinear two-field system, second equation','U_t=(JU) cross V','Preserve U_t with an uncertainty note; V_t is a plausible emendation, not established by the autograph.','Both readings are mathematically consequential; the manuscript writes U.','both','ambiguity')

item(514,'P000964','problem','Borel summation of the Gaussian tail',r'Gelfand asks for the divergent asymptotic expansion of \(\int_x^\infty e^{-t^2}\,dt\) and its summation by Borel’s method.',r'For \(x>0\), put \(z=x^{-2}\) and \(F(z)=2xe^{x^2}\int_x^\infty e^{-t^2}\,dt\). Then \(F(z)\sim\sum_{n\ge0}(-1)^n(1/2)_n z^n\), whose Borel transform is \((1+s)^{-1/2}\). Its positive-direction Laplace sum \(z^{-1}\int_0^\infty e^{-s/z}(1+s)^{-1/2}\,ds\) equals \(F(z)\).','E',r'The asymptotic expansion is classical; \citet[§7.12(i), Eq.~7.12.1]{nist2026dlmf} records it and remainder bounds. The elementary substitution \(t^2=x^2+s x^2\) proves the stated Borel integral.',['nist2026dlmf'],correct='correct',match='exact',speaker='I. M. Gelfand',area='asymptotic analysis')
item(514,'P000965','method','Yang–Baxter connections and unitarity',r'The diagram connects factorized scattering, two-dimensional statistical mechanics, integrable systems, and quantum one-dimensional systems. Belavin adds unitarity conditions.',r'In a specified factorized relativistic theory, a two-body matrix must satisfy the Yang--Baxter consistency relation; physical unitarity and crossing impose additional independent restrictions. Transfer-matrix and continuum constructions relate certain such matrices to lattice and differential models.','E',r'These relationships already occur in \citet[§§1--2]{belavin1980discrete}; the more detailed construction follows in record 516. They recur from 1978-453.19, 1978-454.3, and 1978-460.14 without creating a new problem.',['belavin1980discrete'],match='partial')
item(515,'P000965','construction','Inversion and partial-transpose dynamics',r'\(\Omega R=R^{-1}\), crossing \(C\) transposes the block indices, \(\Omega^2=C^2=1\), and the product is said to have no finite order.',r'On the Zariski-open set where the required inverses exist, inversion and partial transpose are birational involutions of projective matrix space. Their product generally has infinite order; special points and invariant subvarieties can have periodic orbits.','B',r'The corresponding birational-involution approach was developed systematically in \citet[§2]{bellonmaillardviallet1991higher}; the paper was received 25 February 1991 and published in October. The match is to the method, not a universal classification.',['bellonmaillardviallet1991higher'],reconstruction='Projectivization, the domain of the rational maps, and the distinction between generic and periodic behaviour are supplied.',match='partial')
item(515,'P000965-P000966','construction','The symmetric eight-vertex subspace',r'The displayed \(4\times4\) matrix has entries \(a,b,c,d\) in the symmetric eight-vertex pattern and is described by two simultaneous \(\mathbb Z_2\) conjugations.',r'For \(V=\mathbb C^2\), the matrices commuting with both \(\sigma_x\otimes\sigma_x\) and \(\sigma_z\otimes\sigma_z\) have the form \(\left(\begin{smallmatrix}a&0&0&d\\0&b&c&0\\0&c&b&0\\d&0&0&a\end{smallmatrix}\right)\). This four-dimensional linear space is preserved by inversion where defined and by partial transpose.','E',r'This is the zero-field eight-vertex family associated with \citet{baxter1971eight}. The minus sign preceding simultaneous conjugation in the notebook is incompatible with literal fixed-point invariance, although a global sign disappears in projective coordinates.',['baxter1971eight'],correct='false as written',verification='publisher metadata checked',match='exact')
item(515,'P000966','theorem','Baxter invariants and the generic elliptic fibre',r'Two invariants are given as \(I_1=(a^2+b^2-c^2-d^2)/(ab)\), \(I_2=cd/(ab)\), and their level sets are called elliptic curves.',r'On \(ab\ne0\), these functions are invariant under the projective inversion/crossing dynamics. In \(\mathbb P^3\), a generic common level is a smooth complete intersection of two quadrics, hence a genus-one curve. Singular levels can degenerate, while the affine level is a cone of dimension two.','E',r'The elliptic parametrization is the Baxter eight-vertex mechanism \citep{baxter1971eight}; later birational treatments are \citet[§2]{bellonmaillardviallet1991higher}. The genus calculation uses adjunction and requires smoothness.',['baxter1971eight','bellonmaillardviallet1991higher'],match='partial',reconstruction='The projective ambient space and generic-smoothness conditions repair the literal dimension and degeneration omissions.')
item(515,'P000965-P000966','question','Invariant varieties beyond the eight-vertex example',r'Belavin asks which varieties are invariant under the inversion/crossing operation, before presenting the eight-vertex answer.',r'For a fixed matrix size, one may study algebraic subvarieties preserved birationally by the composition of inverse and partial transpose. The notes do not specify a dimension, an equivalence relation, or a requirement to classify all such subvarieties.','F',r'\citet{bellonmaillardviallet1991higher} studies higher-dimensional examples and their invariants, providing a thematic continuation. It does not identify a unique comprehensive problem posed by this sentence.',['bellonmaillardviallet1991higher'],correct='not determinable',match='thematic only',confidence='medium',status='As of November 2026, the eight-vertex example is established; no determinate global classification question is reconstructed from the broader sentence.')
correction('P000965','simultaneous Z2 conjugation','R maps to -g^{-1} tensor g^{-1} R g tensor g','Remove the leading minus for literal invariance; alternatively explicitly work projectively.','Autograph contains a leading minus; conjugation fixes the displayed nonzero eight-vertex matrix without that sign.')
correction('P000966','invariant level sets','elliptic curves','generic smooth projective common levels are genus-one curves','Two homogeneous quadrics in P3; affine common levels are two-dimensional cones and special fibres may be singular.')

item(516,'P000966','remark','From factorized scattering to spin chains and spin fields',r'The programme runs from a factorized particle theory through the eight-vertex model and the XYZ chain to the Landau--Lifshitz equation.',r'This is a sequence of model-dependent identifications and limits: vertex weights define transfer matrices, logarithmic derivatives at a regular spectral value give spin-chain Hamiltonians, and suitable long-wave classical limits give spin-field equations.','E',r'The eight-vertex and quantum inverse-scattering ingredients predate the lecture \citep{baxter1971eight,sklyaninfaddeev1978quantum}. The note expressly omits the Baxter step and provides no general limit theorem.',['baxter1971eight','sklyaninfaddeev1978quantum'],match='partial',verification='publisher metadata checked')
item(516,'P000966-P000967','definition','Two-body amplitudes and factorization',r'Particles have equal mass and \(d\) internal types. Each crossing contributes \(S_{ij}^{kl}\), and a many-particle amplitude is the product summed over internal labels.',r'In elastic factorized scattering in \(1+1\) dimensions, the two-body amplitude acts on \(V\otimes V\), \(\dim V=d\). Lorentz invariance makes its spectral variable a rapidity difference. Summing internal states in an ordered product gives the many-body amplitude; unitarity is an additional condition.','E',r'Compare the rapidity formulation in \citet[§1]{belavin1980discrete}. An ordinary angle in a Euclidean spacetime sketch is not the invariant rapidity.',['belavin1980discrete'],match='exact')
item(516,'P000967','theorem','Three-line consistency gives the Yang–Baxter equation',r'It is enough to slide one vertex past the intersection of two other lines. Equation (12) gives the component relation.',r'Consistency of the two resolutions of a generic three-particle collision requires \(S_{12}(\alpha)S_{13}(\alpha+\beta)S_{23}(\beta)=S_{23}(\beta)S_{13}(\alpha+\beta)S_{12}(\alpha)\). For generic line arrangements with fixed endpoints, triangle moves together with commuting disjoint crossings generate the relevant reorderings.','E',r'The factorization relation is explicitly developed in \citet[§1]{belavin1980discrete}; it recurs from 1978-454.3. The notebook’s component equation has a mismatched free lower index on its right-hand side.',['belavin1980discrete'],correct='false as written',match='exact')
item(516,'P000967','problem','Finding a nontrivial two-body Yang–Baxter matrix',r'The stated problem is to find \(S\); the note contrasts \(d^6\) component relations with \(d^4\) unknown functions.',r'For a chosen internal space and spectral-parameter convention, construct non-scalar meromorphic matrices satisfying the Yang--Baxter relation. The counts \(d^6,d^4\) count written components and entries; they do not prove algebraic independence or nonexistence.','E',r'The elliptic two-state answer is given on the next page and derives from the Baxter family \citep{baxter1971eight}. The sentence does not demand a classification of all meromorphic solutions.',['baxter1971eight'],verification='publisher metadata checked',match='partial',correct='correct')
item(516,'P000967-P000968','construction','Tensor-leg notation with noncommutative coefficients',r'\(S\) is rewritten in matrix-unit notation and the relation generalized to \(R_{12}S_{13}S^{\prime}_{23}=S^{\prime}_{23}S_{13}R_{12}\), with coefficients in an associative algebra \(D\).',r'Let \(V_1,V_2\) be finite-dimensional complex auxiliary spaces and \(\mathcal A\) a unital associative algebra. An exchange relation is an identity in \(\operatorname{End}(V_1\otimes V_2)\otimes\mathcal A\), with numeric \(R\) on the two auxiliary legs and the entries of the two monodromy matrices in \(\mathcal A\).','E',r'This is the algebraic transfer-matrix mechanism of quantum inverse scattering \citep{sklyaninfaddeev1978quantum}. The reconstruction distinguishes an algebra of coefficients from an additional finite-dimensional matrix factor.',['sklyaninfaddeev1978quantum'],match='partial',verification='publisher metadata checked')
item(516,'P000968','theorem','The commuting-transfer-operator lemma',r'The theorem claims commutativity after writing \(\operatorname{tr}_3 S_{13}\) and \(\operatorname{tr}_3 S^{\prime}_{23}\).',r'Assume \(R\) is an invertible numeric operator and \(R_{12}T_1T_2=T_2T_1R_{12}\). Then \([\operatorname{tr}_{V_1}T_1,\operatorname{tr}_{V_2}T_2]=0\) in \(\mathcal A\). This follows by conjugating with \(R\) and taking both auxiliary traces; tracing the common quantum leg is not this theorem.','E',r'The standard mechanism underlies \citet{sklyaninfaddeev1978quantum}. Its elementary proof uses cyclicity only for the numeric \(R\), so it remains valid for noncommuting coefficient entries.',['sklyaninfaddeev1978quantum'],correct='false as written',reconstruction='The auxiliary trace legs and invertibility of R are supplied explicitly.',match='partial',verification='publisher metadata checked')
item(516,'P000968','construction','The elliptic Pauli-matrix solution',r'\(S(\alpha)=\sum_{j=0}^3w_j\sigma_j\otimes\sigma_j\), with \(w_0=1\) and ratios of \(\operatorname{sn},\operatorname{cn},\operatorname{dn}\) at \(x\) and \(x+\alpha\).',r'The recorded two-state matrix is the elliptic eight-vertex family in a Pauli basis, defined meromorphically away from the poles of the ratios. A common elliptic modulus and a fixed crossing parameter are understood; scalar normalization and a permutation of Pauli axes do not change the exchange mechanism.','E',r'This is an explicit special-family construction associated with \citet{baxter1971eight}; the reference verifies the model and elliptic solution, not every normalization in the notebook.',['baxter1971eight'],match='partial',verification='publisher metadata checked',confidence='medium',status='As of November 2026, the elliptic family is standard. The displayed normalization is retained as a source formula, without a claim that all its meromorphic or degenerating parameter values are regular.')
item(516,'P000968','method','A parameter family yields commuting transfer matrices',r'For a one-parameter family \(S\), an \(R(\alpha,\alpha^{\prime})\) intertwines \(S(\alpha)\) and \(S(\alpha^{\prime})\), yielding commuting trace operators.',r'If the invertible auxiliary exchange relation holds for every pair of regular parameters, the correctly traced transfer operators \(t(\alpha)\) satisfy \([t(\alpha),t(\alpha^{\prime})]=0\). Taylor or logarithmic coefficients commute wherever those operations are defined.','E',r'This is the family form of the preceding lemma and the construction used in \citet{sklyaninfaddeev1978quantum}. No independence or completeness of the resulting integrals follows merely from their commutativity.',['sklyaninfaddeev1978quantum'],match='partial',verification='publisher metadata checked')
correction('P000967','component Yang–Baxter relation (12), final factor on RHS',r'S_{j_1k_3}^{j_1j_3}',r'S_{i_1k_3}^{j_1j_3}','Autograph and both transcriptions repeat j1; free-index balance and the adjacent tensor relation require i1.')
correction('P000966-P000967','relativistic scattering angle','ordinary angle / hyperbolic cosine of momentum','rapidity difference (with rapidity parametrizing the mass shell)','The diagram is Euclidean; Lorentz invariance uses a hyperbolic rapidity parameter, as in Belavin 1980 §1.')
correction('P000968','transfer-matrix theorem',r'[tr_3 S_13,tr_3 Sprime_23]=0',r'[tr_1 S_13,tr_2 Sprime_23]=0, with invertible numeric R_12','Scan confirms tr3; the exchange relation proves commutativity only after auxiliary traces.')
