correction('P000980','unique extremal cones','unique Cmin and Cmax','unique positive extremal cones after choosing a central orientation','Their negatives give the opposite pair; Olshanskii1981 §1 fixes positivity.','both','faithful_error')
correction('P000980','irreducible factorization','irreducible equals holomorphic tensor antiholomorphic for Gamma(C)','the checked theorem is for Gamma(Cmin), with its covering and contractive representation category','Olshanskii1981 Cor5.8 explicitly uses the minimal cone.','both','faithful_error')
correction('P000980','maximal domain of extension','exact domain of extendibility','maximal domain of contractive holomorphic semigroup extension in the stated category','The generator inequality encodes contractivity; it does not prohibit every other analytic continuation of matrix coefficients.','both','ambiguity')
save()

